/**
 * A service's ER diagrams (qits-2014), published beside `entities.json` in its
 * `@contracts/<application>` docs site: `database/index.json` lists each persistence unit, its
 * diagram's file and the entities it holds, and each `database/<file>.md` is generated by
 * `qits database diagram` with one fenced `mermaid` block holding the unit's `erDiagram`. Both are
 * files a release publishes, not API answers, so their types live here and {@link asDatabaseIndex}
 * checks the index's shape at run time. A bundle published before qits-2014 has neither file.
 */

/** One entity a unit holds. */
export interface DatabaseEntity {
  /** Its fully qualified class name, as `entities.json` names it. */
  readonly entity: string;
  /** Its table; null when the index names none. */
  readonly table: string | null;
}

/** One persistence unit and its diagram's file, relative to `database/`. */
export interface DatabaseUnit {
  readonly unit: string;
  readonly file: string;
  readonly entities: readonly DatabaseEntity[];
}

/** A service's `database/index.json`: the fields the app reads (others are ignored). */
export interface DatabaseIndex {
  readonly formatVersion: number;
  readonly units: readonly DatabaseUnit[];
}

const isObject = (value: unknown): value is Record<string, unknown> =>
  !!value && typeof value === 'object' && !Array.isArray(value);

const isString = (value: unknown): value is string => typeof value === 'string';

const isEntity = (value: unknown): value is Record<string, unknown> =>
  isObject(value) && isString(value['entity']);

const isUnit = (value: unknown): value is Record<string, unknown> & { entities: unknown[] } =>
  isObject(value) &&
  isString(value['unit']) &&
  isString(value['file']) &&
  Array.isArray(value['entities']) &&
  value['entities'].every(isEntity);

/**
 * `value` as a database index when it has the index's shape (a numeric `formatVersion` and a
 * `units` list, each with a `unit`, a `file` and its `entities`), else null. A missing `table`
 * reads as null.
 */
export function asDatabaseIndex(value: unknown): DatabaseIndex | null {
  if (!isObject(value) || typeof value['formatVersion'] !== 'number') return null;
  const units = value['units'];
  if (!Array.isArray(units) || !units.every(isUnit)) return null;
  return {
    formatVersion: value['formatVersion'],
    units: units.map((unit) => ({
      unit: unit['unit'] as string,
      file: unit['file'] as string,
      entities: (unit.entities as Record<string, unknown>[]).map((e) => ({
        entity: e['entity'] as string,
        table: isString(e['table']) ? e['table'] : null,
      })),
    })),
  };
}

/** The unit whose entities list `entity` (a fully qualified class name); null when none does. */
export function unitOf(index: DatabaseIndex, entity: string): DatabaseUnit | null {
  return index.units.find((unit) => unit.entities.some((e) => e.entity === entity)) ?? null;
}

/**
 * The body of the first fenced `mermaid` block in `markdown` (the definition, without the fence),
 * trimmed; null when it holds none.
 */
export function mermaidOf(markdown: string): string | null {
  const block = /^```mermaid[^\S\n]*\n([\s\S]*?)^```[^\S\n]*$/m.exec(
    markdown.replace(/\r\n/g, '\n'),
  );
  const definition = block?.[1].trim();
  return definition ? definition : null;
}
